#!/bin/sh
# SPEC 505.mcf_r test: arms capstone-lifetimes in that order, each in a fresh copy of in/ under /tmp/sr.
# Generated by capstone/ports/spec-cpu2017/board/make-stage.py from runcpu's own command files.
S=$(cd "$(dirname "$0")" && pwd)
V=${SPEC_VEXEC:?set SPEC_VEXEC to the batch launcher}
export CAPSTONE_VM_STATS=1
n=0
gtsnap() { echo "@@GT-SNAP$1 $2 hpm=$(cat /sys/module/capstone_vm/parameters/hpm_snapshot 2>/dev/null || echo NA) vm=$(grep -E '^(pgfault|pgmajfault|pgalloc_normal|pgfree|pgactivate|nr_free_pages) ' /proc/vmstat | tr ' \n' ':,') st=$(grep -E '^(ctxt|processes|intr) ' /proc/stat | cut -d' ' -f1-2 | tr ' \n' ':,') mem=$(grep -E '^(MemFree|MemAvailable):' /proc/meminfo | tr -s ' ' | tr ' \n' ':,')"; }
echo "@@THP $(cat /sys/kernel/mm/transparent_hugepage/enabled) thp=$(cat /sys/module/capstone_vm/parameters/thp)"
bench() { dmesg | grep 'capstone_vm: bench' | tail -1 | sed 's/.*capstone_vm: //'; }
nbench() { dmesg | grep -c 'capstone_vm: bench'; }
up() { cut -d' ' -f1 /proc/uptime; }
# the module's cumulative in-context counters (sysfs, 0444): their delta over a command sums every context it ran
sysb() { for f in cycles instret entries; do cat /sys/module/capstone_vm/parameters/bench_$f 2>/dev/null || echo 0; done | tr '\n' ' '; }
echo "@@SPEC-STAGE 505.mcf_r test arms=capstone-lifetimes commands=1 validations=0"
echo "@@SPEC-ARM-BEGIN capstone-lifetimes"
cd / && rm -rf /tmp/sr && mkdir -p /tmp/sr && cp -a "$S/in/." /tmp/sr/ && cd /tmp/sr || exit 1
echo "@@SPEC-BEGIN $n run capstone-lifetimes 0"
s0=$(sysb)
u0=$(up)
gtsnap 0 $n
"$V" "$S/bin/capstone-lifetimes/mcf_r_base.capstone-lifetimes" inp.in > inp.out 2>> inp.err
rc=$?
gtsnap 1 $n
echo "@@THP-VMSTAT $(grep -E '^thp_(fault_alloc|fault_fallback|split_page|collapse_alloc) ' /proc/vmstat | tr ' \n' ':,')"
u1=$(up)
s1=$(sysb)
sys=$(echo $s0 $s1 | awk '{printf "%.0f,%.0f,%.0f", $4-$1, $5-$2, $6-$3}')
echo "@@SPEC-END $n run capstone-lifetimes 0 rc=$rc up0=$u0 up1=$u1 sys=$sys nbench=$(nbench) $(grep -a CAPSTONE_VM_STATS inp.err 2>/dev/null | tail -1) :: $(bench)"
n=$((n+1))
echo "@@SPEC-HASH-BEGIN capstone-lifetimes"
find . -type f | sort | while read -r f; do sha256sum "$f"; done
echo "@@SPEC-HASH-END capstone-lifetimes"
if [ -f inp.err ] && [ $(wc -c < inp.err) -le ${SPEC_INBAND_MAX:-65536} ]; then echo "@@SPEC-FILE capstone-lifetimes inp.err"; gzip -9c inp.err | base64; echo "@@SPEC-FILE-END"; fi
if [ -f inp.out ] && [ $(wc -c < inp.out) -le ${SPEC_INBAND_MAX:-65536} ]; then echo "@@SPEC-FILE capstone-lifetimes inp.out"; gzip -9c inp.out | base64; echo "@@SPEC-FILE-END"; fi
if [ -f mcf.out ] && [ $(wc -c < mcf.out) -le ${SPEC_INBAND_MAX:-65536} ]; then echo "@@SPEC-FILE capstone-lifetimes mcf.out"; gzip -9c mcf.out | base64; echo "@@SPEC-FILE-END"; fi
echo "@@SPEC-ARM-END capstone-lifetimes"
cd / && rm -rf /tmp/sr /tmp/sw
echo "@@SPEC-DONE 505.mcf_r test"
